const payload = $json;
if (payload.consent_required !== true || payload.service_authenticated !== true || !Array.isArray(payload.items)) {
  throw new Error('Marketing audience contract failed closed');
}
return payload.items.map((item) => ({ json: { ...item, approved_for_automation: true, source_contract: 'LATEST_EXPLICIT_CONSENT', send_enabled: false } }));

const DAY = 24 * 60 * 60 * 1000;
const now = Date.now();
const output = [];
for (const input of $input.all()) {
  const item = input.json;
  const scenarios = [];
  if (item.request_status === 'AWAITING_PREPAYMENT') scenarios.push('PAYMENT_REMINDER');
  if (item.request_status === 'EXPIRED') scenarios.push('LOST_LEAD_RECOVERY');
  const checkoutRaw = item.actual_check_out_at || item.reservation_check_out || item.request_check_out;
  const checkout = checkoutRaw ? new Date(checkoutRaw).getTime() : NaN;
  const checkedOut = item.stay_status === 'CHECKED_OUT' || item.reservation_status === 'CHECKED_OUT';
  if (checkedOut && Number.isFinite(checkout) && checkout <= now) {
    scenarios.push('POST_STAY');
    if (now - checkout >= 60 * DAY) scenarios.push('SEASONAL_RETURN');
  }
  for (const scenario of scenarios) {
    output.push({ json: { ...item, scenario, send_enabled: false, review_required: true } });
  }
}
return output;
